---- UPDATE FACTURA TIPODCTO FA
UPDATE TRADE
SET TRADE.CODVEN = 'P76'
WHERE   CODVEN IN('03') AND NRODCTO IN('107451') AND TIPODCTO='FA' --AND CIUDADCLI='FUNZA'
---- UPDATE FACTURA TIPODCTO FR
UPDATE TRADE
SET TRADE.CODVEN = 'P76'
WHERE   CODVEN IN('03') AND NRODCTO IN('108739') AND CIUDADCLI='MEDELLIN' AND TIPODCTO='FR'

----UPDATE FACTURA TIPODCTO AN
UPDATE TRADE
SET TRADE.CODVEN = 'P47'
WHERE    NRODCTO IN('12833')  AND TIPODCTO='AN'

----UPDATE NOTACREDITO TIPODCTO NC
UPDATE TRADE
SET TRADE.CODVEN = 'P66'
WHERE   CODVEN IN('P27') AND NRODCTO IN('61821')AND TIPODCTO='NC'
----UPDATE NOTA DEBITO TIPODCTO ND
UPDATE TRADE
SET TRADE.CODVEN = 'P47'
WHERE NRODCTO IN('2734') and TIPODCTO='Nd'
---- UPDATE PEDIDOS TIPODCTO PD
UPDATE TRADE
SET TRADE.CODVEN = 'P74'
WHERE   CODVEN IN('P58') AND NRODCTO IN('20240530') AND TIPODCTO='PD' AND CIUDADCLI='PEREIRA'